// Read-only actual finite Query/RS elimination and whole-W directional audit.
// No physical Solver, source rewrite, successful-subset acceptance, or GPU change.
#include "rinkfit/joint_builder.hpp"
#include <Eigen/SVD>
#include <iostream>
#include <chrono>
using namespace rinkfit;
using Json=eventio::Json;
namespace {
template<class T>std::vector<T> readbin(const std::filesystem::path&f,std::size_t n){auto b=eventio::bytes(f);if(b.size()!=n*sizeof(T))throw std::runtime_error("auxiliary size mismatch "+f.string());std::vector<T>v(n);std::memcpy(v.data(),b.data(),b.size());return v;}
template<class T>void writebin(const std::filesystem::path&f,const std::vector<T>&v){std::ofstream o(f,std::ios::binary);o.write(reinterpret_cast<const char*>(v.data()),v.size()*sizeof(T));if(!o)throw std::runtime_error("output write failed");}
struct Row {bool valid=false,derivative=false,fdvalid=false;std::array<double,3>x{};Eigen::Matrix3d J=Eigen::Matrix3d::Zero();Vec2<double>uv{NAN,NAN},d{NAN,NAN},fd{NAN,NAN};std::string reason;double condition=INFINITY,fdstep=NAN;int geometry_segment=-1,query_segment=-1;};
JointRowEvaluation evaluator(const JointEventModel&m,const JointObservation&o){JointRowEvaluation q;q.model=&m;q.observation=&o;q.layout=o.layout(m);for(std::size_t k=0;k<q.layout.block_ids.size();++k)q.parameter_sizes[int(k)]=int(m.blocks[q.layout.block_ids[k]].values.size());return q;}
Row evaluate(const JointEventModel&m,const JointObservation&o,bool derivative,bool fd){Row r;auto q=evaluator(m,o);auto p=m.pointers(q.layout);if(!q.local_solution_uncached(p.data(),o.station,&r.x,&r.J)){r.reason="finite_local_RS_Query_root_unresolved";return r;}if(!o.station_allowed(m,o.path,r.x[0])||r.x[1]<0||r.x[1]>1079){r.reason="root_outside_exact_finite_station_or_sensor";return r;}auto pp=m.predict_explicit(q.layout,r.x[0],r.x[1],p.data());if(!pp.valid()){r.reason="native_projection_domain_invalid";return r;}const auto visible=m.visibility(q.layout,r.x[0],r.x[1],p.data());if(!visible.visible()){r.reason="physical_surface_visibility_invalid";return r;}if(o.width_block>=0)for(int k:{5,6})if(m.measurement_domain(q.layout,r.x[0],p.data(),k)>0){r.reason="paint_measurement_domain_invalid";return r;}auto certified=m.project_rs(q.layout,r.x[0],r.x[1]);if(!certified.valid||std::abs(certified.row-r.x[1])>1e-7){r.reason="independent_native_RS_certificate_or_row_mismatch";return r;}r.uv=pp.uv;r.valid=true;const auto&path=m.materials.at(o.material).paths.at(o.path);if(path.points.size()>1)r.geometry_segment=std::min(int(path.points.size())-2,int(std::floor(r.x[0]*(path.points.size()-1))));if(o.query)r.query_segment=int(std::upper_bound(o.query->alpha.begin(),o.query->alpha.end(),r.x[2])-o.query->alpha.begin())-1;if(o.query){Eigen::JacobiSVD<Eigen::Matrix3d>svd(r.J);auto s=svd.singularValues();r.condition=s[0]/s[2];}if(!derivative)return r;
using K=ceres::Jet<double,1>;std::vector<std::vector<K>>store;std::vector<const K*>kp;store.reserve(p.size());kp.reserve(p.size());for(std::size_t k=0;k<p.size();++k){store.emplace_back();for(std::size_t j=0;j<m.blocks[q.layout.block_ids[k]].values.size();++j){K z(p[k][j]);if(int(k)==q.layout.optics_slot&&j==0)z.v[0]=1;store.back().push_back(z);}kp.push_back(store.back().data());}Vec2<K>e;if(!q.native_error(kp.data(),&e)){r.reason="implicit_directional_chain_failed";return r;}r.d={e[0].v[0],e[1].v[0]};r.derivative=finite_array(r.d);if(!fd)return r;
// FD independently re-solves the full local equations in both directions.
std::array<K,3>dy;if(!q.nuisance(kp.data(),&dy))return r;double h=1e-3;auto limit=[&](double x,double dx,double lo,double hi){if(std::abs(dx)>1e-15)h=std::min(h,.25*std::min(x-lo,hi-x)/std::abs(dx));};if(r.geometry_segment>=0){const double length=double(path.points.size()-1);limit(r.x[0],dy[0].v[0],r.geometry_segment/length,(r.geometry_segment+1)/length);}if(o.query&&!o.query->den.size()&&r.query_segment>=0)limit(r.x[2],dy[2].v[0],o.query->alpha[r.query_segment],o.query->alpha[std::min(r.query_segment+1,int(o.query->alpha.size())-1)]);limit(r.x[1],dy[1].v[0],0.,1079.);r.fdstep=h;if(!std::isfinite(h)||h<=1e-10)return r;Vec2<double>v[2];bool ok=true;for(int side=0;side<2;++side){std::vector<std::vector<double>>ss;std::vector<const double*>sp;ss.reserve(p.size());sp.reserve(p.size());for(std::size_t k=0;k<p.size();++k){auto len=m.blocks[q.layout.block_ids[k]].values.size();ss.emplace_back(p[k],p[k]+len);if(int(k)==q.layout.optics_slot)ss.back()[0]+=(side?1:-1)*h;sp.push_back(ss.back().data());}std::array<double,3>x;Eigen::Matrix3d J;if(!q.local_solution_uncached(sp.data(),o.station,&x,&J)){ok=false;break;}auto pv=m.predict_explicit(q.layout,x[0],x[1],sp.data());if(!pv.valid()){ok=false;break;}if(r.geometry_segment>=0&&std::min(int(path.points.size())-2,int(std::floor(x[0]*(path.points.size()-1))))!=r.geometry_segment){ok=false;break;}if(o.query&&o.query->den.empty()&&int(std::upper_bound(o.query->alpha.begin(),o.query->alpha.end(),x[2])-o.query->alpha.begin())-1!=r.query_segment){ok=false;break;}v[side]=pv.uv;}if(ok){r.fd={(v[1][0]-v[0][0])/(2*h),(v[1][1]-v[0][1])/(2*h)};r.fdvalid=finite_array(r.fd);}return r;}
}
int main(int argc,char**argv){try{if(argc!=5)throw std::runtime_error("usage: formal_query_transition MODEL PACKET COMPLETE_CAPTURE_CANDIDATE OUT");const auto start=std::chrono::steady_clock::now();auto m=JointEventModel::load(argv[1]);auto p=JointPacket::load(argv[2],m);const std::filesystem::path candidate=std::filesystem::u8path(argv[3]),out=std::filesystem::u8path(argv[4]);if(std::filesystem::exists(out))throw std::runtime_error("immutable output exists");std::filesystem::create_directories(out);const auto binding=eventio::read_json(candidate/"source_uv_capture_state_binding.json");if(binding.at("packet_sha256")!=p.source_hash||binding.at("model_sha256")!=eventio::file_sha256(argv[1]))throw std::runtime_error("complete capture binding differs");const auto manifest=eventio::read_json(candidate/"explicit_nuisance/manifest.json");const auto n=p.rows.size();std::vector<double>s,v,a;std::vector<std::uint32_t>b;for(const auto*name:{"station.f64","row.f64","alpha.f64","path.u32"})eventio::verify(candidate/"explicit_nuisance"/name,manifest.at("files").at(name).at("sha256"));s=readbin<double>(candidate/"explicit_nuisance/station.f64",n);v=readbin<double>(candidate/"explicit_nuisance/row.f64",n);a=readbin<double>(candidate/"explicit_nuisance/alpha.f64",n);b=readbin<std::uint32_t>(candidate/"explicit_nuisance/path.u32",n);for(std::size_t i=0;i<n;++i){auto&r=p.rows[i];if(r.kind==1&&s[i]!=r.station)throw std::runtime_error("fixed entity station changed");r.station=s[i];r.row=v[i];r.alpha=a[i];r.path=int(b[i]);}
std::vector<Row>rows(n);std::vector<double>uv(2*n,NAN),error(2*n,NAN),direction(2*n,NAN),fd(2*n,NAN),roots(3*n,NAN);std::vector<unsigned char>valid(n),dvalid(n),fdvalid(n);std::vector<unsigned>counts(n);std::size_t active=0,qcount=0,qvalid=0,dfail=0,fdfail=0,fixed=0;double fdworst=0,rootmax=0;std::map<std::string,std::size_t>failure;Json byshot=Json::object();std::ofstream ledger(out/"query_rows.jsonl");
for(std::size_t i=0;i<n;++i){const auto&o=p.rows[i];if(!o.active)continue;++active;if(o.kind==1)++fixed;rows[i]=evaluate(m,o,true,o.query!=nullptr);auto&r=rows[i];if(o.query)++qcount;if(r.valid){valid[i]=1;uv[2*i]=r.uv[0];uv[2*i+1]=r.uv[1];error[2*i]=r.uv[0]-o.uv[0];error[2*i+1]=r.uv[1]-o.uv[1];for(int k=0;k<3;++k)roots[3*i+k]=r.x[k];if(r.derivative){dvalid[i]=1;direction[2*i]=r.d[0];direction[2*i+1]=r.d[1];}else ++dfail;if(o.query){++qvalid;Vec2<double>q;o.query->point(r.x[2],&q);rootmax=std::max(rootmax,std::hypot(q[0]-r.uv[0],q[1]-r.uv[1]));if(r.fdvalid){fdvalid[i]=1;fd[2*i]=r.fd[0];fd[2*i+1]=r.fd[1];for(int k=0;k<2;++k)fdworst=std::max(fdworst,std::abs(r.d[k]-r.fd[k])/std::max({1.,std::abs(r.d[k]),std::abs(r.fd[k])}));}else ++fdfail;}}else ++failure[r.reason];
if(o.query){auto&st=byshot[o.shot_id];if(st.is_null())st={{"total",0},{"valid",0},{"failed",0}};st["total"]=st["total"].get<int>()+1;st[r.valid?"valid":"failed"]=st[r.valid?"valid":"failed"].get<int>()+1;Json row={{"row",i},{"source_row_id",o.source_row_id},{"shot",o.shot_id},{"native_pts",o.pts},{"material",o.material},{"label",m.materials.at(o.material).label},{"path",o.path},{"UV",o.uv},{"rational",!o.query->den.empty()},{"alpha_bounds",{o.query->alpha.front(),o.query->alpha.back()}},{"stored_auxiliary",{o.station,o.row,o.alpha}},{"root_valid",r.valid},{"failure",r.reason},{"derivative_valid",r.derivative},{"FD_valid",r.fdvalid}};if(r.valid){row["root"]=r.x;row["source_2D_error"]=Vec2<double>{error[2*i],error[2*i+1]};row["J_condition"]=r.condition;row["J3x3"]=std::vector<double>(r.J.data(),r.J.data()+9);row["J_layout"]="column_major: equations RS,query_u,query_v; variables station,row,alpha";row["cx_IFD_direction"]=r.d;row["FD_step_cx_px"]=r.fdstep;row["geometry_segment"]=r.geometry_segment;row["query_segment"]=r.query_segment;if(r.fdvalid)row["cx_FD_direction"]=r.fd;}ledger<<row.dump()<<'\n';}if(active%10000==0)std::cout<<"rows "<<active<<" / "<<n<<std::endl;}
std::size_t groupvalid=0,groupfailed=0,rank=0,failedrank=0,querygroups=0;long double half=0,grad=0;std::vector<double>wr,wd;std::vector<unsigned char>wok;std::ofstream gl(out/"query_W_groups.jsonl");for(const auto&g:p.groups){bool ok=true,dok=true,hasq=false;for(auto i:g.rows){++counts[i];ok&=valid[i]!=0;dok&=dvalid[i]!=0;hasq|=bool(p.rows[i].query);}rank+=g.rank;wok.push_back(ok&&dok);if(ok&&dok)++groupvalid;else {++groupfailed;failedrank+=g.rank;}Json record={{"id",g.id},{"statistic_kind",g.statistic_kind},{"rows",g.rows},{"rank",g.rank},{"whole_group_valid",ok&&dok},{"no_W_cross_terms_dropped",true}};long double gcost=0,gder=0;for(std::size_t k=0;k<g.rank;++k){double z=0,d=0;if(ok&&dok)for(std::size_t j=0;j<g.rows.size();++j)for(int c=0;c<2;++c){double w=g.W[k*2*g.rows.size()+2*j+c];z+=w*error[2*g.rows[j]+c];d+=w*direction[2*g.rows[j]+c];}else z=d=NAN;wr.push_back(z);wd.push_back(d);if(ok&&dok){gcost+=.5L*z*z;gder+=(long double)z*d;}}if(ok&&dok){half+=gcost;grad+=gder;}if(hasq){++querygroups;record["half_cost"]=ok&&dok?Json(double(gcost)):Json(nullptr);record["cx_directional_cost_derivative"]=ok&&dok?Json(double(gder)):Json(nullptr);gl<<record.dump()<<'\n';}}
bool accounted=true;for(std::size_t i=0;i<n;++i)accounted&=counts[i]==unsigned(p.rows[i].active);writebin(out/"root_valid.u8",valid);writebin(out/"root_station_row_alpha.f64",roots);writebin(out/"predicted_UV.f64",uv);writebin(out/"source_2D_error.f64",error);writebin(out/"cx_IFD_direction.f64",direction);writebin(out/"cx_FD_direction.f64",fd);writebin(out/"cx_IFD_valid.u8",dvalid);writebin(out/"cx_FD_valid.u8",fdvalid);writebin(out/"whole_W_residual.f64",wr);writebin(out/"whole_W_cx_direction.f64",wd);writebin(out/"whole_W_group_valid.u8",wok);
Json report={{"schema","rinkfit.actual_formal_implicit_Query_W_transition_audit.v1"},{"model",{{"file",argv[1]},{"sha256",eventio::file_sha256(argv[1])}}},{"packet",{{"file",argv[2]},{"sha256",p.source_hash}}},{"parent_token",binding.at("state_token")},{"raw_rows",n},{"active_rows",active},{"fixed_entities_RS_only",fixed},{"Query_count",qcount},{"Query_valid_roots",qvalid},{"Query_failed_roots_retained",qcount-qvalid},{"Query_by_shot",byshot},{"root_failures",failure},{"maximum_Query_equality_px",rootmax},{"directional_J_failed",dfail},{"Query_FD_failed",fdfail},{"Query_cx_IFD_FD_max_scaled_error",fdworst},{"direction","simultaneous +1px principal cx in each observed rig; exact row-local IFT then complete group W"},{"all_group_count",p.groups.size()},{"Query_groups",querygroups},{"statistical_rank",rank},{"whole_group_valid",groupvalid},{"whole_group_failed_retained",groupfailed},{"failed_group_rank_retained",failedrank},{"all_active_source_exactly_once_in_groups",accounted},{"whole_W_half_cost",groupfailed?Json(nullptr):Json(double(half))},{"whole_W_cx_directional_derivative",groupfailed?Json(nullptr):Json(double(grad))},{"known_noise_W_all_rank_valid",failedrank==0},{"known_noise_W_half_cost",failedrank?Json(nullptr):Json(double(half))},{"known_noise_W_cx_directional_derivative",failedrank?Json(nullptr):Json(double(grad))},{"available_groups_are_not_full_objective",true},{"source_UV_E_W_Query_or_finite_domains_changed",false},{"physical_parameters_changed",false},{"ordinary_nonQuery_station_policy","complete CP value retained as a joint coordinate; this directional audit does not eliminate it"},{"local_Query_h_exactly_eliminated_before_W",true},{"W_cross_row_terms_preserved",true},{"formal_trial_accepted",false},{"physical_Solver_started",false},{"production_mode_transition_installed",false},{"whole_connected_source_order_consumed",false},{"quality_accepted",false},{"elapsed_seconds",std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()}};eventio::atomic_json(out/"report.json",report);std::cout<<report.dump(2)<<std::endl;return 0;}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}}
